  requireUri(uri);
  if (subscriptions.has(uri)) {
    throw invalidParams('already subscribed to uri: ' + uri);
  }
  subscriptions.add(uri);
  return { subscribed: true };
}

export async function unsubscribeResource(uri) {
  requireUri(uri);
  if (!subscriptions.has(uri)) {
    throw invalidParams('not subscribed to uri: ' + uri);
  }
  subscriptions.delete(uri);
  return { unsubscribed: true };
}

const TOOLS = [
  {
    name: 'subscribeResource',
    description: 'Subscribe to a resource by URI. Rejects empty URIs and duplicates.',
    inputSchema: {
      type: 'object',
      properties: {
        uri: { type: 'string', description: 'The resource URI to subscribe to.' },
      },
      required: ['uri'],
    },
  },
  {
    name: 'unsubscribeResource',
    description: 'Unsubscribe from a resource by URI. Rejects missing subscriptions.',
    inputSchema: {
      type: 'object',
      properties: {
        uri: { type: 'string', description: 'The resource URI to unsubscribe from.' },
      },
      required: ['uri'],
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'subscribeResource':
      return await subscribeResource(args.uri);
    case 'unsubscribeResource':
